mapper.select:
SELECT count
FROM pet_collections
WHERE account_id = #{accountId}
  AND item_id = #{itemId}

mapper.insert:
INSERT INTO pet_collections (
    account_id, item_id, count, discovered, updated_at
) VALUES (
    #{accountId}, #{itemId}, 1, 1, #{updatedAt}
)
ON CONFLICT(account_id, item_id) DO UPDATE
SET count = count + 1,
    discovered = 1,
    updated_at = #{updatedAt}

mapper.update:
UPDATE pet_collections
SET count = count - #{quantity},
    discovered = 1,
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND item_id = #{itemId}
  AND discovered = 1
  AND count >= #{quantity}
